adcs_status_t status;
adcs_vec3_t zero_vec = {0, 0, 0};
adcs_actuator_command_t zero_cmd = {{0, 0, 0}, 0};
adcs_bdot_state_t state;
adcs_vec3_t dummy_rate;

if ((previous == NULL) || (current == NULL) || (rate == NULL) || 
    (command == NULL) || (torque == NULL)) {
    return ADCS_E_NULL;
}

if ((!isfinite(previous_time)) || (!isfinite(current_time)) || 
    (current_time <= previous_time) || 
    (!isfinite(gain)) || (!isfinite(limit)) || 
    (gain < 0.0) || (limit < 0.0)) {
    *rate = zero_vec;
    *command = zero_cmd;
    *torque = zero_vec;
    return ADCS_E_RANGE;
}

// Initialize state to ensure it acts as if starting fresh or using provided history
state.previous_field_t = zero_vec;
state.previous_time_s = 0.0;
state.initialized = 0;

// Step 1: Initialize history with previous sample
status = adcs_bdot_update(&state, previous, previous_time, 1.0, &dummy_rate);
if (status != ADCS_OK) {
    *rate = zero_vec;
    *command = zero_cmd;
    *torque = zero_vec;
    return status;
}

// Step 2: Update with current sample to get rate
status = adcs_bdot_update(&state, current, current_time, 1.0, rate);
if (status != ADCS_OK) {
    *rate = zero_vec;
    *command = zero_cmd;
    *torque = zero_vec;
    return status;
}

// Step 3: Compute dipole command
status = adcs_bdot_dipole(current, rate, gain, limit, command);
if (status != ADCS_OK) {
    *command = zero_cmd;
    *torque = zero_vec;
    return status;
}

// Step 4: Verify torque = m x B
*torque = adcs_vec3_cross(&command->command, current);

return ADCS_OK;

